#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Gera os assets do DX Ingest Eventos a partir do logo audiovisual
enviado pelo Rafael, sem precisar subir arquivo binário ao GitHub.

Por que base64 aqui: a integração do GitHub só empurra texto UTF-8;
PNG/ICO subidos por ela chegam corrompidos (caso já visto no Dashboard DX).
Este script é texto puro e, no runner do GitHub Actions, recria os
arquivos binários antes do PyInstaller.

- assets/logo.png: logo completo redimensionado (splash / Sobre)
- assets/icon.png: ícone derivado — diafragma do logo + seta de descarga
- assets/icon.ico: mesmo ícone, nos tamanhos 16, 32, 48 e 256
"""

