def main():
    from PIL import Image

    here = Path(__file__).parent
    assets = here / "assets"
    assets.mkdir(exist_ok=True)
    logo_path = assets / "logo.png"
    icon_png = assets / "icon.png"
    icon_ico = assets / "icon.ico"
    logo_path.write_bytes(base64.b64decode("".join(LOGO_512_B64)))
    icon_png.write_bytes(base64.b64decode("".join(ICON_512_B64)))
    img = Image.open(icon_png)
    img.save(icon_ico, sizes=[(16, 16), (32, 32), (48, 48), (256, 256)])
    print(f"logo: {logo_path} ({logo_path.stat().st_size} bytes)")
    print(f"icone: {icon_ico} ({icon_ico.stat().st_size} bytes)")


if __name__ == "__main__":
    main()
